INSERT INTO learn_game_content_sets (category_id,name,difficulty,is_active) SELECT c.id,'Benda di Sekitarku','easy',1 FROM learn_game_categories c WHERE c.name='Kata Benda Anak' AND NOT EXISTS (SELECT 1 FROM learn_game_content_sets s WHERE s.category_id=c.id AND s.name='Benda di Sekitarku');
INSERT INTO learn_game_content_sets (category_id,name,difficulty,is_active) SELECT c.id,'Aku di Sekolah','easy',1 FROM learn_game_categories c WHERE c.name='Kosakata Sekolah' AND NOT EXISTS (SELECT 1 FROM learn_game_content_sets s WHERE s.category_id=c.id AND s.name='Aku di Sekolah');
INSERT INTO learn_game_content_sets (category_id,name,difficulty,is_active) SELECT c.id,'Kata Matematika','easy',1 FROM learn_game_categories c WHERE c.name='Istilah Matematika Dasar' AND NOT EXISTS (SELECT 1 FROM learn_game_content_sets s WHERE s.category_id=c.id AND s.name='Kata Matematika');
INSERT INTO learn_game_content_sets (category_id,name,difficulty,is_active) SELECT c.id,'Tumbuhan dan Lingkungan','medium',1 FROM learn_game_categories c WHERE c.name='Alam dan Tumbuhan' AND NOT EXISTS (SELECT 1 FROM learn_game_content_sets s WHERE s.category_id=c.id AND s.name='Tumbuhan dan Lingkungan');
INSERT INTO learn_game_content_sets (category_id,name,difficulty,is_active) SELECT c.id,'Sains di Sekitar Kita','medium',1 FROM learn_game_categories c WHERE c.name='Istilah Sains Kelas 7' AND NOT EXISTS (SELECT 1 FROM learn_game_content_sets s WHERE s.category_id=c.id AND s.name='Sains di Sekitar Kita');
